CALENDAR_DATE = rb"[0-9]{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12][0-9]|3[01])|(?:0[469]|11)-(?:0[1-9]|[12][0-9]|30)|02-(?:0[1-9]|1[0-9]|2[0-9]))"
CLOCK_TIME = rb"(?:[01][0-9]|2[0-3]):[0-5][0-9]:(?:[0-5][0-9]|60)(?:\.[0-9]+)?"
UTC_OFFSET = rb"(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])"
VALUE = CALENDAR_DATE + rb"T" + CLOCK_TIME + UTC_OFFSET
